import "net/http"

// APIError is returned by handlers and rendered as the contract error envelope.
type APIError struct {
	Status  int
	Code    string
	Message string
}

func (e *APIError) Error() string { return e.Code + ": " + e.Message }

func apiErr(status int, code, msg string) *APIError {
	return &APIError{Status: status, Code: code, Message: msg}
}

func errBadRequest(code, msg string) *APIError { return apiErr(http.StatusBadRequest, code, msg) }
func errConflict(code, msg string) *APIError   { return apiErr(http.StatusConflict, code, msg) }
func errNotFound(msg string) *APIError         { return apiErr(http.StatusNotFound, "not_found", msg) }
func errForbidden(msg string) *APIError        { return apiErr(http.StatusForbidden, "forbidden", msg) }
func errInvalidJSON(msg string) *APIError      { return errBadRequest("invalid_json", msg) }
func errUnauthorized() *APIError {
	return apiErr(http.StatusUnauthorized, "unauthorized", "authentication required")
}
