{"command": "create", "path": "/workspace/backend/internal/app/db.go", "file_text": "package app

import (
	"context"
	"crypto/pbkdf2"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"log"
	"strconv"
	"strings"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// queryer is satisfied by both *pgxpool.Pool and pgx.Tx.
type queryer interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
}

func newID() string {
	var b [16]byte
	_, _ = rand.Read(b[:])
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	h := hex.EncodeToString(b[:])
	return h[0:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:32]
}

func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return base64.RawURLEncoding.EncodeToString(b)
}

const pbkdf2Iterations = 120000

func hashPassword(pw string) string {
	salt := make([]byte, 16)
	_, _ = rand.Read(salt)
	key, _ := pbkdf2.Key(sha256.New, pw, salt, pbkdf2Iterations, 32)
	return fmt.Sprintf("pbkdf2$%d$%s$%s", pbkdf2Iterations, base64.RawStdEncoding.EncodeToString(salt), base64.RawStdEncoding.EncodeToString(key))
}

func verifyPassword(hash, pw string) bool {
	parts := strings.Split(hash, "$")
	if len(parts) != 4 || parts[0] != "pbkdf2" {
		return false
	}
	iter, err := strconv.Atoi(parts[1])
	if err != nil {
		return false
	}
	salt, err := base64.RawStdEncoding.DecodeString(parts[2])
	if err != nil {
		return false
	}
	want, err := base64.RawStdEncoding.DecodeString(parts[3])
	if err != nil {
		return false
	}
	got, err := pbkdf2.Key(sha256.New, pw, salt, iter, len(want))
	if err != nil {
		return false
	}
	return subtle.ConstantTimeCompare(got, want) == 1
}

// defaultSampleTypes are always present: Amber, Indigo, Frost and Pulse.
type defaultSampleType struct {
	Name          string
	Qualification string
	Container     string
	MinC, MaxC    float64
	Cooled        bool
	Batching      bool
}

var defaultSampleTypes = []defaultSampleType{
	{Name: "Amber", Qualification: "amber", Container: "standard_vial", MinC: 15, MaxC: 30, Cooled: false, Batching: true},
	{Name: "Indigo", Qualification: "indigo", Container: "sealed_tube", MinC: 15, MaxC: 30, Cooled: false, Batching: true},
	{Name: "Frost", Qualification: "frost", Container: "cryo_vial", MinC: -25, MaxC: -10, Cooled: true, Batching: true},
	{Name: "Pulse", Qualification: "pulse", Container: "rapid_cartridge", MinC: 15, MaxC: 30, Cooled: false, Batching: false},
}

func seedDefaults(ctx context.Context, pool *pgxpool.Pool) error {
	ids := map[string]string{}
	for _, t := range defaultSampleTypes {
		var id string
		err := pool.QueryRow(ctx, `SELECT id FROM sample_types WHERE name=$1`, t.Name).Scan(&id)
		if err == pgx.ErrNoRows {
			id = newID()
			if _, err := pool.Exec(ctx, `INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
				VALUES ($1,$2,true,$3,$4,$5,$6,$7,$8)`, id, t.Name, t.Qualification, t.Container, t.MinC, t.MaxC, t.Cooled, t.Batching); err != nil {
				return fmt.Errorf("seed sample type %s: %w", t.Name, err)
			}
		} else if err != nil {
			return err
		}
		ids[t.Name] = id
	}
	// Indigo must not share a container with Amber (mutual incompatibility).
	if _, err := pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = array_append(array_remove(incompatible_sample_types, $2::uuid), $2::uuid) WHERE id=$1`, ids["Indigo"], ids["Amber"]); err != nil {
		return err
	}
	if _, err := pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = array_append(array_remove(incompatible_sample_types, $2::uuid), $2::uuid) WHERE id=$1`, ids["Amber"], ids["Indigo"]); err != nil {
		return err
	}
	return nil
}

func (a *App) ensureInitialAdmin(ctx context.Context) error {
	var count int
	if err := a.pool.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	if a.cfg.AdminUsername == "" || a.cfg.AdminPassword == "" {
		log.Println("no users exist and ADMIN_USERNAME/ADMIN_PASSWORD are not set; skipping initial administrator")
		return nil
	}
	id := newID()
	_, err := a.pool.Exec(ctx, `INSERT INTO users (id, username, password_hash, full_name, roles, active) VALUES ($1,$2,$3,$4,$5,true)`,
		id, a.cfg.AdminUsername, hashPassword(a.cfg.AdminPassword), "Initial Administrator", []string{RoleAdministrator})
	if err != nil {
		return fmt.Errorf("create initial admin: %w", err)
	}
	a.auditSystem(ctx, a.pool, "initial_admin_created", "user", id, map[string]any{"username": a.cfg.AdminUsername})
	log.Printf("created initial administrator %q", a.cfg.AdminUsername)
	return nil
}
