	"github.com/gorilla/websocket"
)

// RealtimeEvent is a durable event delivered over the /api/events stream.
type RealtimeEvent struct {
	ID         int64          `json:"id"`
	Type       string         `json:"type"`
	EntityType string         `json:"entityType"`
	EntityID   string         `json:"entityId"`
	Payload    map[string]any `json:"payload"`
	CreatedAt  time.Time      `json:"createdAt"`

	roles   []string
	userIDs []string
}

func (e RealtimeEvent) visibleTo(sess *Session) bool {
	if len(e.roles) == 0 && len(e.userIDs) == 0 {
		return true
	}
	for _, u := range e.userIDs {
		if u == sess.UserID {
			return true
		}
	}
	if sess.ActiveRole != "" {
		for _, r := range e.roles {
			if r == sess.ActiveRole {
				return true
			}
		}
	}
	return false
}

// Hub fans committed events out to connected websocket subscribers.
type Hub struct {
	mu   sync.Mutex
	subs map[chan RealtimeEvent]struct{}
}

func NewHub() *Hub { return &Hub{subs: map[chan RealtimeEvent]struct{}{}} }

func (h *Hub) Subscribe() chan RealtimeEvent {
	ch := make(chan RealtimeEvent, 256)
	h.mu.Lock()
	h.subs[ch] = struct{}{}
	h.mu.Unlock()
	return ch
}

func (h *Hub) Unsubscribe(ch chan RealtimeEvent) {
	h.mu.Lock()
	delete(h.subs, ch)
	h.mu.Unlock()
}

func (h *Hub) Publish(e RealtimeEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for ch := range h.subs {
		select {
		case ch <- e:
		default:
		}
	}
}

func (r *Req) emit(typ, entityType, entityID string, payload map[string]any, roles []string, userIDs []string) {
	if payload == nil {
		payload = map[string]any{}
	}
	r.events = append(r.events, pendingEvent{Type: typ, EntityType: entityType, EntityID: entityID, Payload: payload, Roles: roles, UserIDs: userIDs})
}

func (r *Req) flushEvents() ([]RealtimeEvent, error) {
	out := make([]RealtimeEvent, 0, len(r.events))
	for _, ev := range r.events {
		e, err := insertEvent(r.ctx, r.tx, ev)
		if err != nil {
			return nil, err
		}
		out = append(out, e)
	}
	r.events = nil
	return out, nil
}

func insertEvent(ctx context.Context, q queryer, ev pendingEvent) (RealtimeEvent, error) {
	payload, _ := json.Marshal(ev.Payload)
	if ev.Roles == nil {
		ev.Roles = []string{}
	}
	if ev.UserIDs == nil {
		ev.UserIDs = []string{}
	}
	e := RealtimeEvent{Type: ev.Type, EntityType: ev.EntityType, EntityID: ev.EntityID, Payload: ev.Payload, roles: ev.Roles, userIDs: ev.UserIDs}
	err := q.QueryRow(ctx, `INSERT INTO realtime_events (type, entity_type, entity_id, payload, audience_roles, audience_user_ids) VALUES ($1,$2,$3,$4,$5,$6) RETURNING id, created_at`,
		ev.Type, ev.EntityType, ev.EntityID, payload, ev.Roles, ev.UserIDs).Scan(&e.ID, &e.CreatedAt)
	return e, err
}

func (a *App) eventsSince(ctx context.Context, sess *Session, since int64, limit int) ([]RealtimeEvent, error) {
	rows, err := a.pool.Query(ctx, `SELECT id, type, entity_type, entity_id, payload, audience_roles, audience_user_ids, created_at FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT $2`, since, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []RealtimeEvent{}
	for rows.Next() {
		var e RealtimeEvent
		var payload []byte
		if err := rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &e.roles, &e.userIDs, &e.CreatedAt); err != nil {
			return nil, err
		}
		e.Payload = map[string]any{}
		_ = json.Unmarshal(payload, &e.Payload)
		if e.visibleTo(sess) {
			out = append(out, e)
		}
	}
	return out, rows.Err()
}

var upgrader = websocket.Upgrader{
	Subprotocols:    []string{"lab-logistics-v1"},
	CheckOrigin:     func(r *http.Request) bool { return true },
	ReadBufferSize:  1024,
	WriteBufferSize: 4096,
}

// handleEvents serves either a websocket stream (with subprotocol auth) or a
// plain JSON poll of durable events after the given cursor.
func (a *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, apiErr(http.StatusMethodNotAllowed, "method_not_allowed", "use GET"))
		return
	}
	token := bearerToken(r)
	protocols := websocket.Subprotocols(r)
	for _, p := range protocols {
		if strings.HasPrefix(p, "bearer.") {
			if decoded, err := base64.RawURLEncoding.DecodeString(strings.TrimRight(p[7:], "=")); err == nil {
				token = string(decoded)
			} else {
				token = p[7:]
			}
		}
	}
	sess, err := a.authenticate(r.Context(), token)
	if err != nil {
		if ae, ok := err.(*APIError); ok {
			writeError(w, ae)
		} else {
			writeError(w, apiErr(http.StatusInternalServerError, "internal_error", "internal error"))
		}
		return
	}
	var since int64
	if s := r.URL.Query().Get("since"); s != "" {
		n, err := strconv.ParseInt(s, 10, 64)
		if err != nil || n < 0 {
			writeError(w, errBadRequest("invalid_json", "since must be a non-negative integer"))
			return
		}
		since = n
	}
	if !websocket.IsWebSocketUpgrade(r) {
		events, err := a.eventsSince(r.Context(), sess, since, 500)
		if err != nil {
			writeError(w, apiErr(http.StatusInternalServerError, "internal_error", "internal error"))
			return
		}
		cursor := since
		if len(events) > 0 {
			cursor = events[len(events)-1].ID
		}
		writeData(w, http.StatusOK, map[string]any{"events": events, "cursor": cursor})
		return
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	sub := a.hub.Subscribe()
	defer a.hub.Unsubscribe(sub)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go func() {
		defer cancel()
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()

	cursor := since
	replay, err := a.eventsSince(ctx, sess, since, 5000)
	if err != nil {
		return
	}
	for _, e := range replay {
		if err := conn.WriteJSON(e); err != nil {
			return
		}
		cursor = e.ID
	}
	ping := time.NewTicker(25 * time.Second)
	defer ping.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ping.C:
			if err := conn.WriteControl(websocket.PingMessage, nil, time.Now().Add(5*time.Second)); err != nil {
				return
			}
		case e := <-sub:
			if e.ID <= cursor {
				continue
			}
			// Re-resolve the session so role-addressed events follow the currently selected role.
			if fresh, err := a.authenticate(ctx, sess.Token); err == nil {
				sess = fresh
			}
			if !e.visibleTo(sess) {
				continue
			}
			if err := conn.WriteJSON(e); err != nil {
				return
			}
			cursor = e.ID
		}
	}
}
