{"command": "create", "path": "/workspace/backend/internal/app/models.go", "file_text": "package app

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
)

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

func (c Coordinate) valid() bool {
	return c.Latitude >= -90 && c.Latitude <= 90 && c.Longitude >= -180 && c.Longitude <= 180
}

type Certification struct {
	Code      string     `json:"code"`
	Active    bool       `json:"active"`
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`
}

type Capacity struct {
	CapacityUnits        int `json:"capacityUnits"`
	ReservedUnits        int `json:"reservedUnits"`
	AvailableUnits       int `json:"availableUnits"`
	CooledCapacityUnits  int `json:"cooledCapacityUnits"`
	CooledReservedUnits  int `json:"cooledReservedUnits"`
	CooledAvailableUnits int `json:"cooledAvailableUnits"`
}

func makeCapacity(cap, reserved, cooledCap, cooledReserved int) Capacity {
	return Capacity{CapacityUnits: cap, ReservedUnits: reserved, AvailableUnits: cap - reserved,
		CooledCapacityUnits: cooledCap, CooledReservedUnits: cooledReserved, CooledAvailableUnits: cooledCap - cooledReserved}
}

type FunctionStates struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

type Location struct {
	ID              string
	Name            string
	Lat, Lng        float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	Functions       FunctionStates
	CapacityUnits   int
	CooledCapacity  int
	Reserved        int
	CooledReserved  int
}

func (l *Location) capacity() Capacity {
	return makeCapacity(l.CapacityUnits, l.Reserved, l.CooledCapacity, l.CooledReserved)
}

func (l *Location) coord() Coordinate { return Coordinate{l.Lat, l.Lng} }

func (l *Location) toJSON() map[string]any {
	return map[string]any{
		"locationId": l.ID, "name": l.Name, "coordinate": l.coord(), "coverageKm": l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes, "active": l.Active, "functions": l.Functions,
	}
}

const locationCols = `id, name, lat, lng, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory, capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units`

func scanLocation(row pgx.Row) (*Location, error) {
	var l Location
	err := row.Scan(&l.ID, &l.Name, &l.Lat, &l.Lng, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory, &l.CapacityUnits, &l.CooledCapacity, &l.Reserved, &l.CooledReserved)
	if err != nil {
		return nil, err
	}
	return &l, nil
}

func loadLocation(ctx context.Context, q queryer, id string) (*Location, error) {
	l, err := scanLocation(q.QueryRow(ctx, `SELECT `+locationCols+` FROM locations WHERE id=$1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	return l, err
}

func loadLocations(ctx context.Context, q queryer) (map[string]*Location, []*Location, error) {
	rows, err := q.Query(ctx, `SELECT `+locationCols+` FROM locations ORDER BY created_at, name`)
	if err != nil {
		return nil, nil, err
	}
	defer rows.Close()
	m := map[string]*Location{}
	var list []*Location
	for rows.Next() {
		l, err := scanLocation(rows)
		if err != nil {
			return nil, nil, err
		}
		m[l.ID] = l
		list = append(list, l)
	}
	return m, list, rows.Err()
