		"roles": u.Roles, "qualifications": u.Qualifications, "certifications": u.Certifications, "active": u.Active,
	}
}

func (u *User) isWorker() bool {
	for _, r := range workerRoles {
		if u.hasRole(r) {
			return true
		}
	}
	return false
}

