var validFunctions = []string{"collection_point", "transfer_point", "hub", "laboratory"}

func functionsFromList(list []string) (FunctionStates, *APIError) {
	var f FunctionStates
	for _, fn := range list {
		switch fn {
		case "collection_point":
			f.CollectionPoint = true
		case "transfer_point":
			f.TransferPoint = true
		case "hub":
			f.Hub = true
		case "laboratory":
