func reserveCapacity(r *Req, journeyID, sampleID, resourceType, resourceID string, cooled bool) error {
	table := "locations"
	if resourceType == "connection" {
		table = "connections"
	}
	col := "reserved_units"
	capCol := "capacity_units"
	if cooled {
		col = "cooled_reserved_units"
		capCol = "cooled_capacity_units"
	}
	tag, err := r.tx.Exec(r.ctx, `UPDATE `+table+` SET `+col+` = `+col+` + 1 WHERE id=$1 AND `+col+` + 1 <= `+capCol, resourceID)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		code := "capacity_exhausted"
		if cooled {
			code = "cooled_capacity_exhausted"
		}
		return errConflict(code, "no capacity available on "+resourceType+" "+resourceID)
	}
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO capacity_reservations (id, journey_id, sample_id, resource_type, resource_id, units, cooled, active) VALUES ($1,$2,$3,$4,$5,1,$6,true)`,
		newID(), journeyID, sampleID, resourceType, resourceID, cooled); err != nil {
		return err
	}
	r.audit("capacity_reserved", resourceType, resourceID, map[string]any{"journeyId": journeyID, "sampleId": sampleID, "cooled": cooled, "units": 1})
	return nil
}

// releaseReservations releases active reservations for a journey, optionally
// restricted to one resource or one sample.
func releaseReservations(r *Req, journeyID string, resourceID string, sampleID string, reason string) error {
	rows, err := r.tx.Query(r.ctx, `SELECT id, sample_id, resource_type, resource_id, cooled FROM capacity_reservations WHERE journey_id=$1 AND active AND ($2='' OR resource_id=$2::uuid) AND ($3='' OR sample_id=$3::uuid)`, journeyID, resourceID, sampleID)
	if err != nil {
		return err
	}
	type res struct {
		id, sample, rtype, rid string
		cooled                 bool
	}
	var list []res
	for rows.Next() {
		var x res
		if err := rows.Scan(&x.id, &x.sample, &x.rtype, &x.rid, &x.cooled); err != nil {
			rows.Close()
			return err
		}
		list = append(list, x)
	}
	rows.Close()
	for _, x := range list {
		table := "locations"
		if x.rtype == "connection" {
			table = "connections"
		}
		col := "reserved_units"
		if x.cooled {
			col = "cooled_reserved_units"
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE `+table+` SET `+col+` = GREATEST(`+col+` - 1, 0) WHERE id=$1`, x.rid); err != nil {
			return err
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE capacity_reservations SET active=false, released_at=$2 WHERE id=$1`, x.id, r.now); err != nil {
			return err
		}
		r.audit("capacity_released", x.rtype, x.rid, map[string]any{"journeyId": journeyID, "sampleId": x.sample, "cooled": x.cooled, "reason": reason})
	}
	return nil
}

// eligibleWorkers returns active workers able to take the assignment, ordered
// by fairness: penalised decliners last, then lowest workload, then least recently offered.
func (a *App) eligibleWorkers(r *Req, as *Assignment, requireAvailable bool) ([]*User, error) {
	role := map[string]string{"collection": RoleCollector, "transport": RoleCourier, "node": RoleNodeHandler, "laboratory": RoleLaboratory}[as.Kind]
	users, err := loadUsersWhere(r.ctx, r.tx, `active AND $1 = ANY(roles)`, role)
	if err != nil {
		return nil, err
	}
	counts := map[string]int{}
	recent := map[string]int{}
	rows, err := r.tx.Query(r.ctx, `SELECT worker_id, count(*) FILTER (WHERE status NOT IN ('completed','cancelled','replaced','expired','pending')), count(*) FILTER (WHERE created_at > $1) FROM assignments WHERE worker_id IS NOT NULL GROUP BY worker_id`, r.now.Add(-24*time.Hour))
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var id string
		var c, rc int
		if err := rows.Scan(&id, &c, &rc); err != nil {
			rows.Close()
			return nil, err
		}
		counts[id], recent[id] = c, rc
	}
	rows.Close()
	var out []*User
	for _, u := range users {
		if requireAvailable && !u.Available {
			continue
		}
		if containsStr(as.DeclinedWorkerIDs, u.ID) {
			continue
		}
		if as.Kind == "node" && (u.AssignedLocationID == nil || as.NodeID == nil || *u.AssignedLocationID != *as.NodeID) {
			continue
		}
		if as.Kind == "laboratory" && (u.AssignedLocationID == nil || as.LaboratoryID == nil || *u.AssignedLocationID != *as.LaboratoryID) {
			continue
		}
		if as.Kind == "collection" && !u.qualifiedFor(as.RequiredQualification, r.now) {
			continue
		}
		if requireAvailable && counts[u.ID] >= u.CapacityUnits {
			continue
		}
		out = append(out, u)
	}
	sort.SliceStable(out, func(i, j int) bool {
		pi := out[i].PenaltyUntil != nil && out[i].PenaltyUntil.After(r.now)
		pj := out[j].PenaltyUntil != nil && out[j].PenaltyUntil.After(r.now)
		if pi != pj {
			return !pi
		}
		if counts[out[i].ID] != counts[out[j].ID] {
			return counts[out[i].ID] < counts[out[j].ID]
		}
		if recent[out[i].ID] != recent[out[j].ID] {
			return recent[out[i].ID] < recent[out[j].ID]
		}
		var ti, tj time.Time
		if out[i].LastOfferedAt != nil {
			ti = *out[i].LastOfferedAt
		}
		if out[j].LastOfferedAt != nil {
			tj = *out[j].LastOfferedAt
		}
		if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		return out[i].Username < out[j].Username
	})
	return out, nil
}

// offerAssignment offers a pending assignment to the single best eligible
// worker. If nobody qualified exists at all, the sample is flagged.
func (a *App) offerAssignment(r *Req, assignmentID string) error {
	as, err := loadAssignment(r.ctx, r.tx, assignmentID, true)
	if err != nil || as == nil {
		return err
	}
	if as.Status != "pending" {
		return nil
	}
	candidates, err := a.eligibleWorkers(r, as, true)
	if err != nil {
		return err
	}
	if len(candidates) == 0 {
		anyQualified, err := a.eligibleWorkers(r, as, false)
		if err != nil {
			return err
		}
		if len(anyQualified) == 0 {
			// Nobody in the system is qualified for this work: flag it right away.
			var declinedOnly bool
			if len(as.DeclinedWorkerIDs) > 0 {
				declinedOnly = true
			}
			if !declinedOnly {
				for _, sid := range as.SampleIDs {
					if err := a.flagNoQualifiedWorker(r, sid, as); err != nil {
						return err
					}
				}
			}
		}
		return nil
	}
	w := candidates[0]
	expires := r.now.Add(a.cfg.OfferTimeout)
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status='offered', worker_id=$2, offered_at=$3, offer_expires_at=$4, updated_at=now() WHERE id=$1`, as.ID, w.ID, r.now, expires); err != nil {
		return err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE users SET last_offered_at=$2 WHERE id=$1`, w.ID, r.now); err != nil {
		return err
	}
	r.audit("assignment_offered", "assignment", as.ID, map[string]any{"workerId": w.ID, "kind": as.Kind, "journeyId": as.JourneyID, "sampleId": as.sampleID(), "sampleIds": as.SampleIDs, "offerExpiresAt": expires})
	r.emit("assignment.offered", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "kind": as.Kind, "workerId": w.ID, "sampleId": as.sampleID(), "journeyId": as.JourneyID, "offerExpiresAt": expires}, opsRoles, []string{w.ID})
	return nil
}

func (a *App) flagNoQualifiedWorker(r *Req, sampleID string, as *Assignment) error {
	s, err := loadSample(r.ctx, r.tx, sampleID, true)
	if err != nil || s == nil {
		return err
	}
	if s.terminal() || s.Status == "exception" {
		return nil
	}
	return a.raiseException(r, s, "no_qualified_worker", "no qualified worker is available for "+as.Kind+" assignment "+as.ID, nil, map[string]any{"assignmentId": as.ID, "kind": as.Kind, "requiredQualification": as.RequiredQualification})
}

// raiseException marks the sample as an exception (distinct from expiry) and records why.
func (a *App) raiseException(r *Req, s *Sample, kind, reason string, labID *string, extra map[string]any) error {
	excID := newID()
	exc := map[string]any{"exceptionId": excID, "kind": kind, "reason": reason, "observedAt": r.now, "recordedBy": r.sess.UserID, "previousStatus": s.Status}
	for k, v := range extra {
		exc[k] = v
	}
	if labID != nil {
		exc["laboratoryId"] = *labID
	}
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO sample_exceptions (id, sample_id, laboratory_id, kind, reason, observed_at, recorded_by) VALUES ($1,$2,$3,$4,$5,$6,$7)`, excID, s.ID, labID, kind, reason, r.now, r.sess.UserID); err != nil {
		return err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status='exception', exception=$2, updated_at=now() WHERE id=$1`, s.ID, mustJSON(exc)); err != nil {
		return err
	}
	s.Status = "exception"
	s.Exception = exc
	r.audit("exception_raised", "sample", s.ID, map[string]any{"kind": kind, "reason": reason, "exceptionId": excID, "laboratoryId": labID})
	r.emit("sample.exception", "sample", s.ID, map[string]any{"sampleId": s.ID, "kind": kind, "reason": reason}, opsRoles, []string{s.Req.RequesterID})
	return nil
}
