{"command": "create", "path": "/workspace/backend/internal/app/requests.go", "file_text": "package app

import (
	"strings"
	"time"
)

func parseTime(s string) (time.Time, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return time.Time{}, false
	}
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05Z07:00", "2006-01-02"} {
		if t, err := time.Parse(layout, s); err == nil {
			return t.UTC(), true
		}
	}
	return time.Time{}, false
}

// requiredTime parses a mandatory timestamp field.
func requiredTime(raw *string, field string) (time.Time, *APIError) {
	if raw == nil {
		return time.Time{}, errInvalidJSON(field + " is required")
	}
	t, ok := parseTime(*raw)
	if !ok {
		return time.Time{}, errBadRequest("invalid_time", field+" must be an RFC 3339 timestamp")
	}
	return t, nil
}

func optionalTime(raw *string, field string) (*time.Time, *APIError) {
	if raw == nil || strings.TrimSpace(*raw) == "" {
		return nil, nil
	}
	t, ok := parseTime(*raw)
	if !ok {
		return nil, errBadRequest("invalid_time", field+" must be an RFC 3339 timestamp")
	}
	return &t, nil
}

type requestInput struct {
	RequesterID             *string     `json:"requesterId"`
	Origin                  *Coordinate `json:"origin"`
	OriginType              string      `json:"originType"`
	OriginNodeID            *string     `json:"originNodeId"`
	RequestedAt             *string     `json:"requestedAt"`
	DeliveryDeadline        *string     `json:"deliveryDeadline"`
