		requesterID = u.ID
	}
	net, err := loadNetwork(r.ctx, r.tx)
	if err != nil {
		return nil, err
	}
	res := net.plan(p.planInput())
	serviceable := res.Reason == "serviceable"
	status, svc := "requested", "serviceable"
	if !serviceable {
		status, svc = "unserviceable", "unserviceable"
	}
	reqID, sampleID, err := a.insertRequestAndSample(r, p, requesterID, false, status, svc, res.Reason)
