		out["targetLaboratoryId"] = res.Laboratory.ID
		ids, err := activeAssignmentIDs(r, sampleID)
		if err != nil {
			return nil, err
		}
		out["activeAssignmentIds"] = ids
	}
	r.emit("sample.requested", "sample", sampleID, map[string]any{"sampleId": sampleID, "requestId": reqID, "serviceability": svc}, opsRoles, []string{requesterID})
	return out, nil
}

func activeAssignmentIDs(r *Req, sampleID string) ([]string, error) {
