	r.audit("presealed_sample_registered", "sample", sampleID, map[string]any{"requestId": reqID, "holderId": r.sess.UserID, "status": "sealed", "serviceability": svc, "reason": res.Reason})
	r.audit("custody_established", "sample", sampleID, map[string]any{"holderId": r.sess.UserID, "role": role})
	out := map[string]any{
		"requestId": reqID, "sampleId": sampleID, "serviceability": svc, "serviceabilityReason": res.Reason,
		"activeAssignmentIds": []string{}, "earliestCollectionAt": p.Earliest, "latestCollectionAt": p.Latest,
		"alreadySealed": true, "originType": p.OriginType,
	}
	if serviceable {
		j, err := a.materializeJourney(r, journeySpec{SampleIDs: []string{sampleID}, SampleType: p.SampleType, Plan: res, OriginCoord: p.Origin, OriginType: p.OriginType, Holder: &holderSpec{UserID: r.sess.UserID, Role: role}, StartAt: p.RequestedAt, Deadline: p.Deadline, Reason: "presealed_ingest"})
		if err != nil {
			return nil, err
		}
		out["journeyId"] = j.ID
		out["targetLaboratoryId"] = res.Laboratory.ID
		ids, err := activeAssignmentIDs(r, sampleID)
		if err != nil {
			return nil, err
		}
		out["activeAssignmentIds"] = ids
	}
	r.emit("sample.ingested", "sample", sampleID, map[string]any{"sampleId": sampleID, "requestId": reqID, "serviceability": svc, "holderId": r.sess.UserID}, opsRoles, []string{requesterID})
	return out, nil
}
