	}
	if as.LastProgressAt != nil && at.Before(*as.LastProgressAt) {
		return nil, errConflict("invalid_progress_time", "occurredAt is earlier than the previous progress update")
	}
	if as.AcceptedAt != nil && at.Before(*as.AcceptedAt) {
		return nil, errConflict("invalid_progress_time", "occurredAt is earlier than acceptance")
	}
	sample, err := loadSample(r.ctx, r.tx, as.sampleID(), true)
	if err != nil {
		return nil, err
	}
	if sample == nil {
		return nil, errNotFound("sample not found")
	}
	if sample.terminal() {
		return nil, errConflict("invalid_sample_state", "sample is "+sample.Status)
	}
	j, err := loadJourney(r.ctx, r.tx, as.JourneyID, false)
	if err != nil {
		return nil, err
	}
	if j == nil || !j.active() {
		return nil, errConflict("assignment_inactive", "journey is not active")
	}
	newStatus := in.Status
	switch as.Kind {
	case "transport":
		cur, ok := transportOrder[as.Status]
		next, ok2 := transportOrder[newStatus]
		if !ok || !ok2 {
			return nil, errConflict("invalid_transition", "status "+newStatus+" is not valid for a transport leg")
		}
		if next <= cur {
			return nil, errConflict("invalid_transition", "cannot move from "+as.Status+" back to "+newStatus)
		}
		if next >= transportOrder["picked_up"] {
			if !sample.Sealed {
				return nil, errConflict("collection_required", "the sample has not been collected and sealed")
			}
			if sample.CurrentHolderID == nil || *sample.CurrentHolderID != r.sess.UserID {
				prev, err := loadAssignmentsWhere(r.ctx, r.tx, `journey_id=$1 AND sequence < $2 AND status NOT IN ('completed','cancelled','replaced','expired')`, as.JourneyID, as.Sequence)
				if err != nil {
					return nil, err
				}
				if len(prev) > 0 {
					return nil, errConflict("prior_leg_incomplete", "the previous leg has not been completed and handed off")
				}
				return nil, errConflict("custody_required", "custody must be transferred to you through a confirmed handoff first")
			}
		}
	case "node", "laboratory":
		if newStatus != "in_progress" && newStatus != "completed" {
			return nil, errConflict("invalid_transition", "node and laboratory assignments only progress to in_progress or completed")
		}
		if newStatus == "completed" {
			return nil, errConflict("invalid_transition", "node work completes through a confirmed outgoing handoff; laboratory work completes through receipt confirmation")
		}
		cur := nodeOrder[as.Status]
		if as.Status == "arrived" {
			cur = 1
		}
		if nodeOrder[newStatus] <= cur {
			return nil, errConflict("invalid_transition", "cannot move from "+as.Status+" to "+newStatus)
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != r.sess.UserID {
			return nil, errConflict("custody_required", "custody must be transferred to you through a confirmed handoff first")
		}
	case "collection":
		return nil, errConflict("invalid_transition", "collection work progresses through collect-and-seal and handoff")
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE assignments SET status=$2, last_progress_at=$3, updated_at=now() WHERE id=$1`, as.ID, newStatus, at); err != nil {
		return nil, err
	}
	sampleStatus := sample.Status
	if as.Kind == "transport" && (newStatus == "picked_up" || newStatus == "in_transit") && sampleStatus != "exception" {
		sampleStatus = "in_transit"
	}
	if as.Kind == "transport" && (newStatus == "arrived" || newStatus == "delivered") && sampleStatus != "exception" {
		sampleStatus = "at_node"
		if as.ToLocationID != nil && sample.TargetLaboratoryID != nil && *as.ToLocationID == *sample.TargetLaboratoryID {
			sampleStatus = "at_laboratory"
		}
	}
	locID := sample.CurrentLocationID
	if as.Kind == "transport" {
		if newStatus == "arrived" || newStatus == "delivered" {
			locID = as.ToLocationID
		} else if newStatus == "in_transit" || newStatus == "picked_up" {
			locID = nil
		}
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status=$2, current_location_id=$3, last_event_at=$4, updated_at=now() WHERE id=$1`, sample.ID, sampleStatus, locID, at); err != nil {
		return nil, err
	}
	if as.Kind == "transport" && (newStatus == "arrived" || newStatus == "delivered") && as.ToLocationID != nil {
		if l, _ := loadLocation(r.ctx, r.tx, *as.ToLocationID); l != nil {
			if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1`, sample.ID, l.Lat, l.Lng, at); err != nil {
				return nil, err
			}
		}
	}
	for _, sid := range as.SampleIDs {
		if sid == sample.ID {
			continue
		}
		if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET status=$2, current_location_id=$3, last_event_at=$4, updated_at=now() WHERE id=$1 AND status NOT IN ('exception','received','cancelled','expired')`, sid, sampleStatus, locID, at); err != nil {
			return nil, err
		}
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE journeys SET status='active', updated_at=now() WHERE id=$1 AND status='planned'`, as.JourneyID); err != nil {
		return nil, err
	}
	r.audit("assignment_progress", "assignment", as.ID, map[string]any{"status": newStatus, "previousStatus": as.Status, "occurredAt": at, "sampleId": sample.ID, "sampleIds": as.SampleIDs, "journeyId": as.JourneyID, "sampleStatus": sampleStatus})
	r.emit("assignment.progress", "assignment", as.ID, map[string]any{"assignmentId": as.ID, "status": newStatus, "sampleId": sample.ID, "sampleStatus": sampleStatus}, opsRoles, []string{sample.Req.RequesterID, r.sess.UserID})
	return map[string]any{"assignmentId": as.ID, "sampleId": sample.ID, "status": newStatus}, nil
}

func (a *App) opRecordWorkerLocation(r *Req) (any, error) {
	var in struct {
		AssignmentID string      `json:"assignmentId"`
		Coordinate   *Coordinate `json:"coordinate"`
		Sequence     *int        `json:"sequence"`
		RecordedAt   *string     `json:"recordedAt"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	if in.Coordinate == nil || !in.Coordinate.valid() {
		return nil, errBadRequest("invalid_coordinate", "coordinate is required and must be in range")
	}
	if in.Sequence == nil || *in.Sequence < 1 {
		return nil, errBadRequest("invalid_sequence", "sequence must be >= 1")
	}
	at, e := requiredTime(in.RecordedAt, "recordedAt")
	if e != nil {
		return nil, e
	}
	as, err := loadAssignment(r.ctx, r.tx, in.AssignmentID, true)
	if err != nil {
		return nil, err
	}
	if as == nil {
		return nil, errNotFound("assignment not found")
	}
	if as.WorkerID == nil || *as.WorkerID != r.sess.UserID {
		return nil, errForbidden("assignment belongs to another worker")
	}
	var lastSeq int
	var lastAt *time.Time
	if err := r.tx.QueryRow(r.ctx, `SELECT COALESCE(max(sequence),0), max(recorded_at) FROM worker_locations WHERE assignment_id=$1`, as.ID).Scan(&lastSeq, &lastAt); err != nil {
		return nil, err
	}
	if *in.Sequence <= lastSeq || (lastAt != nil && at.Before(*lastAt)) {
		return nil, errConflict("stale_location", "a newer location was already recorded for this assignment")
	}
	if _, err := r.tx.Exec(r.ctx, `INSERT INTO worker_locations (worker_id, assignment_id, lat, lng, sequence, recorded_at) VALUES ($1,$2,$3,$4,$5,$6)`, r.sess.UserID, as.ID, in.Coordinate.Latitude, in.Coordinate.Longitude, *in.Sequence, at); err != nil {
		return nil, err
	}
	if _, err := r.tx.Exec(r.ctx, `UPDATE users SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE id=$1 AND (location_recorded_at IS NULL OR location_recorded_at <= $4)`, r.sess.UserID, in.Coordinate.Latitude, in.Coordinate.Longitude, at); err != nil {
		return nil, err
	}
	// Samples in the worker's custody move with the worker.
	if _, err := r.tx.Exec(r.ctx, `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE current_holder_id=$1 AND (location_recorded_at IS NULL OR location_recorded_at <= $4)`, r.sess.UserID, in.Coordinate.Latitude, in.Coordinate.Longitude, at); err != nil {
		return nil, err
	}
	r.audit("worker_location_recorded", "assignment", as.ID, map[string]any{"workerId": r.sess.UserID, "coordinate": *in.Coordinate, "sequence": *in.Sequence, "recordedAt": at, "sampleId": as.sampleID()})
	r.emit("worker.location", "worker", r.sess.UserID, map[string]any{"workerId": r.sess.UserID, "assignmentId": as.ID, "coordinate": *in.Coordinate, "sequence": *in.Sequence, "recordedAt": at}, opsRoles, nil)
	return map[string]any{"assignmentId": as.ID, "coordinate": *in.Coordinate, "sequence": *in.Sequence, "recordedAt": at}, nil
}

// schedulerLoop expires unanswered offers, retries pending work and flags
// assignments that nobody qualified has been able to take within the timeout.
func (a *App) schedulerLoop() {
	t := time.NewTicker(5 * time.Second)
	defer t.Stop()
	for range t.C {
		if err := a.sweepOffers(); err != nil {
			log.Printf("scheduler: %v", err)
		}
	}
}

func (a *App) requestOfferSweep() {
	go func() {
		time.Sleep(200 * time.Millisecond)
		if err := a.sweepOffers(); err != nil {
			log.Printf("scheduler: %v", err)
		}
	}()
}

func (a *App) sweepOffers() error {
	a.mu.Lock()
	defer a.mu.Unlock()
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	tx, err := a.pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	r := &Req{ctx: ctx, app: a, tx: tx, now: time.Now().UTC(), op: "scheduler", sess: &Session{UserID: "system", Roles: []string{"system"}, ActiveRole: "system"}}

	expired, err := loadAssignmentsWhere(ctx, tx, `status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < $1`, r.now)
	if err != nil {
		return err
	}
	for _, as := range expired {
		if err := a.declineOffer(r, as, *as.WorkerID, "expired", "offer timed out", r.now); err != nil {
			return err
		}
	}
	pending, err := loadAssignmentsWhere(ctx, tx, `status='pending' AND journey_id IN (SELECT id FROM journeys WHERE status IN ('planned','active'))`)
	if err != nil {
		return err
	}
	for _, as := range pending {
		if err := a.offerAssignment(r, as.ID); err != nil {
			return err
		}
		after, err := loadAssignment(ctx, tx, as.ID, false)
		if err != nil {
			return err
		}
		if after.Status == "pending" && after.PendingSince != nil && r.now.Sub(*after.PendingSince) > a.cfg.NoWorkerTimeout {
			for _, sid := range after.SampleIDs {
				if err := a.flagNoQualifiedWorker(r, sid, after); err != nil {
					return err
				}
			}
			if _, err := tx.Exec(ctx, `UPDATE assignments SET pending_since=$2 WHERE id=$1`, as.ID, r.now); err != nil {
				return err
			}
		}
	}
	if err := r.flushAudits(); err != nil {
		return err
	}
	events, err := r.flushEvents()
	if err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return err
	}
	for _, e := range events {
		a.hub.Publish(e)
	}
	return nil
}
