		"collectionAssignmentIds": orEmpty(collectionIDs), "nodeAssignmentIds": orEmpty(nodeIDs), "laboratoryAssignmentIds": orEmpty(labIDs),
		"valid": j.active() || j.Status == "completed",
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = *j.ParentJourneyID
	}
	if len(collectionIDs) > 0 {
		out["collectionAssignmentId"] = collectionIDs[0]
	}
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
		if len(transportIDs) > 2 {
			out["middleTransportAssignmentId"] = transportIDs[1]
		}
	}
	if j.ReplanStatus != "" {
		out["replanStatus"] = j.ReplanStatus
	}
	if includeNested {
		if j.ReplacementJourneyID != nil {
			if rj, _ := loadJourney(r.ctx, r.tx, *j.ReplacementJourneyID, false); rj != nil {
				if plan, err := a.journeyPlanJSON(r, rj, false); err == nil {
