			if sj, _ := loadJourney(r.ctx, r.tx, *j.SplitJourneyID, false); sj != nil {
				if plan, err := a.journeyPlanJSON(r, sj, false); err == nil {
					out["splitJourney"] = plan
				}
			}
		}
	}
	return out, nil
}

func orEmpty(l []string) []string {
	if l == nil {
		return []string{}
	}
	return l
}

// routeAvailableCapacity is the tightest remaining capacity across the journey's reserved resources.
func (a *App) routeAvailableCapacity(r *Req, j *Journey) int {
	rows, err := r.tx.Query(r.ctx, `SELECT DISTINCT resource_type, resource_id, cooled FROM capacity_reservations WHERE journey_id=$1 AND active`, j.ID)
	if err != nil {
		return 0
	}
	defer rows.Close()
	min := -1
	for rows.Next() {
		var rtype, rid string
		var cooled bool
		if err := rows.Scan(&rtype, &rid, &cooled); err != nil {
			return 0
		}
		var avail int
		table := "locations"
		if rtype == "connection" {
			table = "connections"
		}
		col := "capacity_units - reserved_units"
		if cooled {
			col = "cooled_capacity_units - cooled_reserved_units"
		}
		if err := r.tx.QueryRow(r.ctx, `SELECT `+col+` FROM `+table+` WHERE id=$1`, rid).Scan(&avail); err != nil {
			continue
		}
		if min < 0 || avail < min {
			min = avail
		}
	}
	if min < 0 {
		return 0
	}
	return min
}

