func (a *App) operationsState(r *Req, sampleTypeFilter string) (map[string]any, error) {
	where := `true`
	args := []any{}
	if sampleTypeFilter != "" {
		where = `r.sample_type_id=$1`
		args = append(args, sampleTypeFilter)
	}
	samples, err := loadSamplesWhere(r.ctx, r.tx, where, args...)
	if err != nil {
		return nil, err
	}
	sampleJSON := []map[string]any{}
	exceptions := []map[string]any{}
	delays := []map[string]any{}
	for _, s := range samples {
		m := map[string]any{"sampleId": s.ID, "sample_id": s.ID, "status": s.Status, "requestId": s.RequestID, "origin": s.Req.Origin, "deliveryDeadline": s.Req.DeliveryDeadline}
		if s.CurrentHolderID != nil {
			m["currentHolderId"] = *s.CurrentHolderID
		}
		if s.ActiveJourneyID != nil {
			m["activeJourneyId"] = *s.ActiveJourneyID
		}
		a.sampleLocationFields(s, m)
		sampleJSON = append(sampleJSON, m)
		if !s.terminal() && s.Status != "unserviceable" && r.now.After(s.Req.DeliveryDeadline) {
			delays = append(delays, map[string]any{"sampleId": s.ID, "kind": "deadline_passed", "deliveryDeadline": s.Req.DeliveryDeadline, "status": s.Status})
		}
	}
	rows, err := r.tx.Query(r.ctx, `SELECT e.id, e.sample_id, e.laboratory_id, e.kind, e.reason, e.observed_at, e.recorded_by, s.status FROM sample_exceptions e JOIN samples s ON s.id=e.sample_id ORDER BY e.created_at DESC`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var id, sid, kind, reason, status string
		var lab, by *string
		var at time.Time
		if err := rows.Scan(&id, &sid, &lab, &kind, &reason, &at, &by, &status); err != nil {
			rows.Close()
			return nil, err
		}
		exceptions = append(exceptions, map[string]any{"exceptionId": id, "sampleId": sid, "laboratoryId": lab, "kind": kind, "reason": reason, "observedAt": at, "recordedBy": by, "sampleStatus": status})
	}
	rows.Close()

	users, err := loadUsersWhere(r.ctx, r.tx, `active AND roles && $1`, workerRoles)
	if err != nil {
		return nil, err
	}
	counts := map[string]int{}
	crow, err := r.tx.Query(r.ctx, `SELECT worker_id, count(*) FROM assignments WHERE worker_id IS NOT NULL AND status NOT IN ('completed','cancelled','replaced','expired','pending') GROUP BY worker_id`)
	if err != nil {
		return nil, err
	}
	for crow.Next() {
		var id string
		var n int
		if err := crow.Scan(&id, &n); err != nil {
			crow.Close()
			return nil, err
		}
		counts[id] = n
	}
	crow.Close()
	workers := []map[string]any{}
	minC, maxC := -1, 0
	for _, u := range users {
		status := "unavailable"
		if u.Available {
			status = "available"
			if minC < 0 || counts[u.ID] < minC {
				minC = counts[u.ID]
			}
			if counts[u.ID] > maxC {
				maxC = counts[u.ID]
			}
		}
		w := map[string]any{"workerId": u.ID, "worker_id": u.ID, "fullName": u.FullName, "roles": u.Roles, "available": u.Available, "status": status, "capacityUnits": u.CapacityUnits, "assignmentCount": counts[u.ID], "locationStale": a.isStale(u.LocationRecordedAt)}
		if u.LatestLat != nil && u.LatestLng != nil {
			w["latestLocation"] = Coordinate{*u.LatestLat, *u.LatestLng}
			w["latest_location"] = Coordinate{*u.LatestLat, *u.LatestLng}
		}
		if u.LocationRecordedAt != nil {
			w["locationRecordedAt"] = *u.LocationRecordedAt
		}
		workers = append(workers, w)
	}
	spread := 0
	if minC >= 0 {
		spread = maxC - minC
	}

	net, err := loadNetwork(r.ctx, r.tx)
	if err != nil {
		return nil, err
	}
	_, locs, err := loadLocations(r.ctx, r.tx)
	if err != nil {
		return nil, err
	}
	locJSON := []map[string]any{}
	for _, l := range locs {
		m := l.toJSON()
		m["id"] = l.ID
		m["capacity"] = l.capacity()
		m["acceptedSampleTypeIds"] = net.acceptedTypes(l.ID)
		locJSON = append(locJSON, m)
	}
	connJSON := []map[string]any{}
	for _, c := range net.connections {
		connJSON = append(connJSON, map[string]any{"id": c.ID, "connectionId": c.ID, "fromLocationId": c.From, "toLocationId": c.To, "travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active, "capacity": c.capacity()})
	}

	journeys, err := loadJourneysWhere(r.ctx, r.tx, `status IN ('planned','active')`)
	if err != nil {
		return nil, err
	}
	routes := []map[string]any{}
	for _, j := range journeys {
		stops, err := loadStops(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		list, err := loadJourneyAssignments(r.ctx, r.tx, j.ID)
		if err != nil {
			return nil, err
		}
		stopJSON := []map[string]any{}
		for _, s := range stops {
			stopJSON = append(stopJSON, s.toJSON())
		}
		legs := []map[string]any{}
		for _, as := range list {
			leg := as.toLeg()
			leg["kind"] = as.Kind
			legs = append(legs, leg)
		}
		route := map[string]any{"journeyId": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": j.SampleIDs, "orderedStops": stopJSON, "legs": legs, "targetLaboratoryId": j.TargetLaboratoryID}
		if j.EstimatedDeliveryAt != nil {
			route["estimatedDeliveryAt"] = *j.EstimatedDeliveryAt
		}
		routes = append(routes, route)
		for _, as := range list {
			if as.Status == "offered" && as.OfferExpiresAt != nil && as.OfferExpiresAt.Before(r.now) {
				delays = append(delays, map[string]any{"journeyId": j.ID, "assignmentId": as.ID, "kind": "offer_overdue", "sampleId": as.sampleID()})
			}
			if as.Status == "pending" {
				delays = append(delays, map[string]any{"journeyId": j.ID, "assignmentId": as.ID, "kind": "unassigned", "sampleId": as.sampleID()})
			}
		}
	}
	handoffs := []map[string]any{}
	hs, err := loadHandoffsWhere(r.ctx, r.tx, `status='pending'`)
	if err != nil {
		return nil, err
	}
	for _, h := range hs {
		handoffs = append(handoffs, h.toJSON())
	}
	var ineligible int
	if err := r.tx.QueryRow(r.ctx, `SELECT count(*) FROM assignments a JOIN users u ON u.id=a.worker_id WHERE a.status IN ('offered','accepted') AND (NOT u.active OR NOT u.available)`).Scan(&ineligible); err != nil {
		return nil, err
	}
	return map[string]any{
		"samples": sampleJSON, "workers": workers, "locations": locJSON, "connections": connJSON, "routes": routes,
		"handoffs": handoffs, "delays": delays, "exceptions": exceptions, "assignmentCountSpread": spread, "ineligibleAssignmentCount": ineligible,
	}, nil
}

func (a *App) opSearchAuditTrail(r *Req) (any, error) {
	var in struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      string  `json:"order"`
	}
	if err := r.parse(&in); err != nil {
		return nil, err
	}
	limit, offset := 500, 0
	if in.Limit != nil {
		if *in.Limit < 1 || *in.Limit > 5000 {
			return nil, errBadRequest("invalid_limit", "limit must be between 1 and 5000")
		}
		limit = *in.Limit
	}
	if in.Offset != nil {
		if *in.Offset < 0 {
			return nil, errBadRequest("invalid_offset", "offset must be >= 0")
		}
		offset = *in.Offset
	}
	order := "newest_first"
	if in.Order != "" {
		if in.Order != "newest_first" && in.Order != "oldest_first" {
			return nil, errBadRequest("invalid_order", "order must be newest_first or oldest_first")
		}
		order = in.Order
	}
	from, e := optionalTime(in.FromTime, "fromTime")
	if e != nil {
		return nil, e
	}
	to, e := optionalTime(in.ToTime, "toTime")
	if e != nil {
