func main() {
	cfg := app.ConfigFromEnv()
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	if len(os.Args) > 1 && os.Args[1] == "reset" {
		if err := app.Reset(ctx, cfg); err != nil {
			log.Fatalf("reset failed: %v", err)
