	}
	defer a.Close()
	if err := a.Init(ctx); err != nil {
		log.Fatalf("init failed: %v", err)
	}

	srv := &http.Server{Addr: cfg.ListenAddr, Handler: a.Router(), ReadHeaderTimeout: 10 * time.Second}
	go func() {
