{"command": "create", "path": "/workspace/backend/internal/app/catalogue.go", "file_text": "package app

import "context"

// buildCatalogue returns the reference data every signed-in user may see:
// sample types and network locations. It is delivered as a realtime event so
// clients can populate forms without a dedicated endpoint.
func buildCatalogue(ctx context.Context, q queryer) (map[string]any, error) {
	_, types, err := loadSampleTypes(ctx, q)
	if err != nil {
		return nil, err
	}
	_, locs, err := loadLocations(ctx, q)
	if err != nil {
		return nil, err
	}
	st := []map[string]any{}
	for _, t := range types {
		st = append(st, t.toJSON())
	}
	ls := []map[string]any{}
	for _, l := range locs {
		ls = append(ls, l.toJSON())
	}
	return map[string]any{"sampleTypes": st, "locations": ls}, nil
}

func (a *App) publishCatalogue(ctx context.Context) error {
	cat, err := buildCatalogue(ctx, a.pool)
	if err != nil {
		return err
	}
	ev, err := insertEvent(ctx, a.pool, pendingEvent{Type: "catalogue.updated", EntityType: "catalogue", EntityID: "catalogue", Payload: cat})
	if err != nil {
		return err
	}
	a.hub.Publish(ev)
	return nil
}

func (r *Req) emitCatalogue() error {
	cat, err := buildCatalogue(r.ctx, r.tx)
	if err != nil {
		return err
	}
	r.emit("catalogue.updated", "catalogue", "catalogue", cat, nil, nil)
	return nil
}
