{"command": "create", "path": "/workspace/frontend/src/lib/session.tsx", "file_text": "import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from 'react'
import { api, getToken, setToken } from './api'
import type { Bootstrap, Location, RealtimeEvent, Role, SampleType } from './types'

export interface Catalogue {
  sampleTypes: SampleType[]
  locations: Location[]
}

interface SessionUser {
  userId: string
  username: string
  fullName?: string
  roles: string[]
  activeRole: string
}

interface SessionState {
  loading: boolean
  user: SessionUser | null
  catalogue: Catalogue
  assignedLocationId: string | null
  /** Monotonic counter bumped whenever a realtime event arrives; pages refetch on change. */
  tick: number
  lastEvent: RealtimeEvent | null
  login: (username: string, password: string) => Promise<void>
  logout: () => void
  selectRole: (role: Role) => Promise<void>
  refresh: () => Promise<void>
}

const SessionContext = createContext<SessionState | null>(null)

function base64url(s: string): string {
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

export function SessionProvider({ children }: { children: ReactNode }) {
  const [loading, setLoading] = useState(true)
  const [user, setUser] = useState<SessionUser | null>(null)
  const [catalogue, setCatalogue] = useState<Catalogue>({ sampleTypes: [], locations: [] })
  const [assignedLocationId, setAssignedLocationId] = useState<string | null>(null)
  const [tick, setTick] = useState(0)
  const [lastEvent, setLastEvent] = useState<RealtimeEvent | null>(null)
  const cursorRef = useRef(0)
  const socketRef = useRef<WebSocket | null>(null)

  const applyEvent = useCallback((ev: RealtimeEvent, userId: string | undefined) => {
    if (ev.id > cursorRef.current) cursorRef.current = ev.id
    if (ev.type === 'catalogue.updated') {
      setCatalogue({
        sampleTypes: (ev.payload.sampleTypes ?? []) as SampleType[],
        locations: (ev.payload.locations ?? []) as Location[],
      })
    }
    if (ev.type === 'user.access' && userId && ev.payload.userId === userId) {
      setAssignedLocationId((ev.payload.assignedLocationId as string) ?? null)
    }
  }, [])

  const loadEventHistory = useCallback(
    async (userId: string) => {
      let since = 0
      for (let page = 0; page < 50; page++) {
        const data = await api.get<{ events: RealtimeEvent[]; cursor: number }>(`events?since=${since}`)
        for (const ev of data.events) applyEvent(ev, userId)
        if (data.events.length < 500) break
        since = data.cursor
      }
    },
    [applyEvent],
  )

  const refresh = useCallback(async () => {
    const token = getToken()
    if (!token) {
      setUser(null)
      setLoading(false)
      return
    }
    try {
      const boot = await api.get<Bootstrap>('ui/bootstrap')
      setUser({ ...boot.user })
      await loadEventHistory(boot.user.userId)
    } catch {
      setToken(null)
      setUser(null)
    } finally {
      setLoading(false)
    }
  }, [loadEventHistory])

  useEffect(() => {
    void refresh()
    const onUnauthorized = () => {
      setUser(null)
    }
    window.addEventListener('labsample:unauthorized', onUnauthorized)
    return () => window.removeEventListener('labsample:unauthorized', onUnauthorized)
  }, [refresh])

  // Live event stream over WebSocket; replays from the last durable cursor on reconnect.
  useEffect(() => {
    if (!user) return
    const token = getToken()
    if (!token) return
    let closed = false
    let retry: number | undefined
    const connect = () => {
      const proto = location.protocol === 'https:' ? 'wss' : 'ws'
      const ws = new WebSocket(`${proto}://${location.host}/api/events?since=${cursorRef.current}`, [
        'lab-logistics-v1',
        `bearer.${base64url(token)}`,
      ])
      socketRef.current = ws
      ws.onmessage = (m) => {
        try {
          const ev = JSON.parse(m.data) as RealtimeEvent
          applyEvent(ev, user.userId)
          setLastEvent(ev)
          setTick((t) => t + 1)
        } catch {
          /* ignore malformed frames */
        }
      }
      ws.onclose = () => {
        if (!closed) retry = window.setTimeout(connect, 3000)
      }
    }
    connect()
    return () => {
      closed = true
      if (retry) window.clearTimeout(retry)
      socketRef.current?.close()
    }
  }, [user?.userId, user?.activeRole, applyEvent])

  const login = useCallback(
    async (username: string, password: string) => {
      const data = await api.post<{ sessionToken: string; userId: string; roles: string[]; activeRole: string }>(
        'authenticate-user',
        { username, password },
      )
      setToken(data.sessionToken)
      setLoading(true)
      await refresh()
    },
    [refresh],
  )

  const logout = useCallback(() => {
    setToken(null)
    setUser(null)
    setAssignedLocationId(null)
    socketRef.current?.close()
  }, [])

  const selectRole = useCallback(async (role: Role) => {
    const data = await api.post<{ activeRole: string; roles: string[] }>('select-active-role', { role })
    setUser((u) => (u ? { ...u, activeRole: data.activeRole, roles: data.roles } : u))
    setTick((t) => t + 1)
  }, [])

  const value = useMemo<SessionState>(
    () => ({ loading, user, catalogue, assignedLocationId, tick, lastEvent, login, logout, selectRole, refresh }),
    [loading, user, catalogue, assignedLocationId, tick, lastEvent, login, logout, selectRole, refresh],
  )
  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>
}

export function useSession(): SessionState {
  const ctx = useContext(SessionContext)
  if (!ctx) throw new Error('useSession must be used inside SessionProvider')
  return ctx
}

export function useLocationName() {
  const { catalogue } = useSession()
  return useCallback(
    (id?: string | null) => {
      if (!id) return '—'
      return catalogue.locations.find((l) => l.locationId === id)?.name ?? id.slice(0, 8)
    },
    [catalogue.locations],
  )
}

export function useSampleTypeName() {
  const { catalogue } = useSession()
  return useCallback(
    (id?: string | null) => {
      if (!id) return '—'
      return catalogue.sampleTypes.find((t) => t.sampleTypeId === id)?.name ?? id.slice(0, 8)
    },
    [catalogue.sampleTypes],
  )
}
