{"command": "create", "path": "/workspace/frontend/src/lib/format.ts", "file_text": "export function fmtTime(iso?: string | null): string {
  if (!iso) return '—'
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return iso
  return d.toLocaleString()
}

export function fmtCoord(c?: { latitude: number; longitude: number } | null): string {
  if (!c) return '—'
  return `${c.latitude.toFixed(5)}, ${c.longitude.toFixed(5)}`
}

export function shortId(id?: string | null): string {
  if (!id) return '—'
  return id.length > 12 ? `${id.slice(0, 8)}…` : id
}

export function humanize(s?: string | null): string {
  if (!s) return '—'
  return s.replace(/[_.]/g, ' ').replace(/^\w/, (c) => c.toUpperCase())
}

/** Datetime-local input value for a date (local time, minute precision). */
export function toLocalInput(d: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`
}

export function fromLocalInput(v: string): string {
  if (!v) return ''
  const d = new Date(v)
  return Number.isNaN(d.getTime()) ? '' : d.toISOString()
}

export function nowIso(): string {
  return new Date().toISOString()
}
