import { Link } from 'react-router-dom'
import { api, describeError } from '../lib/api'
import { useSession } from '../lib/session'
import { ROLE_LABELS, type AssignmentWorkItem, type Role, type RoleWork, type RoleWorkItem } from '../lib/types'
import { fmtTime, humanize } from '../lib/format'
import { Alert, Panel, StaleBadge, StatusBadge, Timeline } from '../components/ui'
import AssignmentCard from '../components/AssignmentCard'

export default function WorkPage() {
  const { user, tick } = useSession()
  const [work, setWork] = useState<RoleWork | null>(null)
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async () => {
    if (!user?.activeRole) return
    try {
      setWork(await api.post<RoleWork>('list-role-work', {}))
      setError(null)
    } catch (err) {
      setError(describeError(err))
    }
  }, [user?.activeRole])

  useEffect(() => {
    void load()
  }, [load, tick])

  if (!user?.activeRole) return null
  const role = user.activeRole as Role
  return (
    <div className="page">
      <h1>My work — {ROLE_LABELS[role] ?? role}</h1>
      {role === 'requester' && (
        <p>
          <Link to="/requests/new" className="btn">
            New collection request
          </Link>
        </p>
      )}
      {error && <Alert kind="error">{error}</Alert>}
      {!work ? (
        <p role="status">Loading work…</p>
      ) : (
        <>
          <Panel title="Pending">
            <WorkList items={work.pending} empty="Nothing pending." onChanged={load} />
          </Panel>
          <Panel title="In progress">
            <WorkList items={work.inProgress} empty="No work in progress." onChanged={load} />
          </Panel>
          <Panel title="Completed">
            <WorkList items={work.completed} empty="No completed work yet." onChanged={load} />
          </Panel>
        </>
      )}
    </div>
  )
}

function WorkList({ items, empty, onChanged }: { items: RoleWorkItem[]; empty: string; onChanged: () => void }) {
  if (items.length === 0) return <p className="muted">{empty}</p>
  return (
    <ul className="work-list">
      {items.map((it) => (
        <li key={itemKey(it)} className="work-item">
          <WorkItemView item={it} onChanged={onChanged} />
        </li>
      ))}
    </ul>
  )
}

function itemKey(it: RoleWorkItem): string {
  if (it.kind === 'sample') return `s-${it.sampleId}`
  if (it.kind === 'journey') return `j-${it.journeyId}`
  return `a-${it.assignmentId}`
}

function WorkItemView({ item, onChanged }: { item: RoleWorkItem; onChanged: () => void }) {
  if (item.kind === 'sample') {
    return (
      <article aria-label={`Sample ${item.sampleId}`}>
        <header className="work-item-header">
          <h3>
            <Link to={`/samples/${item.sampleId}`}>Sample {item.sampleId.slice(0, 8)}</Link>
          </h3>
          <StatusBadge status={item.status} />
          {item.serviceability && <StatusBadge status={item.serviceability} />}
        </header>
        <p className="muted">
          Requested {fmtTime(item.requestedAt)} · Deadline {fmtTime(item.deliveryDeadline)}
        </p>
        <StaleBadge stale={item.locationStale} recordedAt={item.locationRecordedAt} />
        <Timeline entries={item.history} />
      </article>
    )
  }
  if (item.kind === 'journey') {
    return (
      <article aria-label={`Journey ${item.journeyId}`}>
        <header className="work-item-header">
          <h3>
            <Link to={`/journeys/${item.journeyId}`}>Journey {item.journeyId.slice(0, 8)}</Link>
          </h3>
          <StatusBadge status={item.status} />
          <span className="muted">
            {humanize(item.routeMode)} · plan v{item.planVersion} · {item.assignmentCount} assignments · ETA {fmtTime(item.estimatedDeliveryAt)}
          </span>
        </header>
        <p>
          Samples:{' '}
          {item.sampleIds.map((s) => (
            <Link key={s} to={`/samples/${s}`} className="chip">
              {s.slice(0, 8)}
            </Link>
          ))}
        </p>
        <Timeline entries={item.history} />
      </article>
    )
  }
  return <AssignmentCard item={item as AssignmentWorkItem} onChanged={onChanged} />
}
