import { api, describeError, newIdempotencyKey } from '../lib/api'
import { useLocationName, useSampleTypeName, useSession } from '../lib/session'
import type { AssignmentWorkItem, JourneyLeg, SampleLifecycle, WorkerJourneyPlan } from '../lib/types'
import { fmtTime, humanize, nowIso } from '../lib/format'
import { Alert, Field, KeyValue, StatusBadge, Timeline } from './ui'

const TRANSPORT_STEPS = ['at_pickup', 'picked_up', 'in_transit', 'arrived', 'delivered'] as const
const NODE_STEPS = ['in_progress', 'completed'] as const

interface Props {
  item: AssignmentWorkItem
  onChanged: () => void
}

export default function AssignmentCard({ item, onChanged }: Props) {
  const { user } = useSession()
  const locName = useLocationName()
  const typeName = useSampleTypeName()
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null)
  const [plan, setPlan] = useState<WorkerJourneyPlan | null>(null)
  const [message, setMessage] = useState<{ kind: 'error' | 'success'; text: string } | null>(null)
  const [busy, setBusy] = useState(false)
  const [showHistory, setShowHistory] = useState(false)

  const finished = ['completed', 'cancelled', 'replaced', 'expired', 'declined'].includes(item.status)
  const offered = item.status === 'offered'
  const active = !finished && !offered

  const loadContext = useCallback(async () => {
    if (!active) return
    try {
      const lc = await api.post<SampleLifecycle>('read-sample-lifecycle', { sampleId: item.sampleId })
      setLifecycle(lc)
      if (item.journeyId) {
        setPlan(await api.post<WorkerJourneyPlan>('read-journey-plan', { journeyId: item.journeyId }))
      }
    } catch {
      /* context is best-effort; actions still surface server errors */
    }
  }, [active, item.sampleId, item.journeyId])

  useEffect(() => {
    void loadContext()
  }, [loadContext, item.status])

  const run = async (label: string, fn: () => Promise<unknown>) => {
    setBusy(true)
    setMessage(null)
    try {
      await fn()
      setMessage({ kind: 'success', text: `${label} recorded.` })
      await loadContext()
      onChanged()
    } catch (err) {
      setMessage({ kind: 'error', text: describeError(err) })
    } finally {
      setBusy(false)
    }
  }

  const myLeg = plan?.legs.find((l) => l.assignmentId === item.assignmentId)
  const nextLeg = myLeg ? plan?.legs.find((l) => l.sequence === myLeg.sequence + 1) : undefined
  const pending = lifecycle?.pendingHandoff
  const iHold = lifecycle?.currentHolderId === user?.userId
  const canConfirmSender = pending && pending.senderId === user?.userId && !pending.senderConfirmed
  const canConfirmReceiver = pending && pending.receiverId === user?.userId && !pending.receiverConfirmed

  return (
    <article className="assignment" aria-label={`${humanize(item.kind)} assignment ${item.assignmentId}`}>
      <header className="work-item-header">
        <h3>
          {humanize(item.kind)} assignment {item.assignmentId.slice(0, 8)}
        </h3>
        <StatusBadge status={item.status} />
        {item.offerExpiresAt && offered && <span className="muted">Offer expires {fmtTime(item.offerExpiresAt)}</span>}
      </header>
      <KeyValue
        items={[
          ['Sample', <Link to={`/samples/${item.sampleId}`}>{item.sampleId.slice(0, 8)}</Link>],
          ...(item.expectedSampleTypeId ? ([['Expected sample type', typeName(item.expectedSampleTypeId)]] as [string, ReactNode][]) : []),
          ...(item.fromLocationId || item.toLocationId
            ? ([['Leg', `${item.fromLocationId ? locName(item.fromLocationId) : 'Origin'} → ${locName(item.toLocationId)}`]] as [string, ReactNode][])
            : []),
          ...(item.nodeId ? ([['Node', locName(item.nodeId)]] as [string, ReactNode][]) : []),
          ...(item.laboratoryId ? ([['Laboratory', locName(item.laboratoryId)]] as [string, ReactNode][]) : []),
          ...(item.incomingFromLocationId ? ([['Incoming from', locName(item.incomingFromLocationId)]] as [string, ReactNode][]) : []),
          ...(item.outgoingToLocationId ? ([['Outgoing to', locName(item.outgoingToLocationId)]] as [string, ReactNode][]) : []),
          ...(item.journeyId ? ([['Journey', <Link to={`/journeys/${item.journeyId}`}>{item.journeyId.slice(0, 8)}</Link>]] as [string, ReactNode][]) : []),
          ...(lifecycle ? ([['Sample status', <StatusBadge status={lifecycle.status} />], ['Custody', iHold ? 'You hold this sample' : lifecycle.currentHolderId ? 'Held by another party' : 'Not yet in custody']] as [string, ReactNode][]) : []),
        ]}
      />
      {item.destinationCapacity && (
        <p className="muted">
          Destination capacity: {item.destinationCapacity.availableUnits}/{item.destinationCapacity.capacityUnits} regular, {item.destinationCapacity.cooledAvailableUnits}/{item.destinationCapacity.cooledCapacityUnits} cooled available
        </p>
      )}
      {message && <Alert kind={message.kind}>{message.text}</Alert>}

      {offered && (
        <div className="actions">
          <button
            type="button"
            className="btn"
            disabled={busy}
            onClick={() => run('Acceptance', () => api.post('accept-assignment', { assignmentId: item.assignmentId, idempotencyKey: newIdempotencyKey() }))}
          >
            Accept assignment
          </button>
          <button
            type="button"
            className="btn btn-secondary"
            disabled={busy}
            onClick={() => run('Decline', () => api.post('decline-assignment', { assignmentId: item.assignmentId, declinedAt: nowIso(), idempotencyKey: newIdempotencyKey() }))}
          >
            Decline assignment
          </button>
        </div>
      )}

      {active && (
        <div className="action-grid">
          {item.kind === 'collection' && lifecycle && !lifecycle.sealed && (
            <CollectSealForm item={item} busy={busy} run={run} />
          )}
          {item.kind === 'transport' && (
            <ProgressForm item={item} steps={TRANSPORT_STEPS} busy={busy} run={run} />
          )}
          {item.kind === 'node' && <ProgressForm item={item} steps={NODE_STEPS} busy={busy} run={run} />}
          {item.kind === 'laboratory' && item.laboratoryId && (
            <LaboratoryActions item={item} laboratoryId={item.laboratoryId} busy={busy} run={run} />
          )}
          <LocationForm item={item} busy={busy} run={run} />
          {(iHold || item.kind === 'collection') && lifecycle?.sealed && <CheckpointForm item={item} busy={busy} run={run} />}
          {pending && (canConfirmSender || canConfirmReceiver) && (
            <div className="subpanel">
              <h4>Pending handoff</h4>
              <p className="muted">
                Sender confirmed: {pending.senderConfirmed ? 'yes' : 'no'} · Receiver confirmed: {pending.receiverConfirmed ? 'yes' : 'no'}
              </p>
              <button
                type="button"
                className="btn"
                disabled={busy}
                onClick={() =>
                  run('Handoff confirmation', () =>
                    api.post('confirm-handoff', {
                      handoffId: pending.handoffId,
                      confirmationSide: canConfirmSender ? 'sender' : 'receiver',
                      confirmedAt: nowIso(),
                      idempotencyKey: newIdempotencyKey(),
                    }),
                  )
                }
              >
                Confirm handoff as {canConfirmSender ? 'sender' : 'receiver'}
              </button>
            </div>
          )}
          {iHold && !pending && nextLeg && nextLeg.workerId && lifecycle?.sealed && (
            <HandoffForm item={item} nextLeg={nextLeg} busy={busy} run={run} />
          )}
        </div>
      )}

      <button type="button" className="link-btn" onClick={() => setShowHistory((s) => !s)} aria-expanded={showHistory}>
        {showHistory ? 'Hide status timeline' : 'Show status timeline'}
      </button>
      {showHistory && <Timeline entries={item.history} />}
    </article>
  )
}

type Runner = (label: string, fn: () => Promise<unknown>) => Promise<void>

