{"command": "create", "path": "/workspace/frontend/src/pages/SamplePage.tsx", "file_text": "import { useCallback, useEffect, useMemo, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { api, describeError } from '../lib/api'
import { useLocationName, useSampleTypeName, useSession } from '../lib/session'
import type { Coordinate, JourneyPlan, SampleLifecycle, SampleState } from '../lib/types'
import { fmtCoord, fmtTime, humanize } from '../lib/format'
import { Alert, Badge, KeyValue, Panel, StaleBadge, StatusBadge, Timeline } from '../components/ui'
import LiveMap, { type MapMarker } from '../components/LiveMap'

export default function SamplePage() {
  const { sampleId = '' } = useParams()
  const { tick, catalogue, user } = useSession()
  const locName = useLocationName()
  const typeName = useSampleTypeName()
  const [state, setState] = useState<SampleState | null>(null)
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null)
  const [plan, setPlan] = useState<JourneyPlan | null>(null)
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async () => {
    try {
      const s = await api.get<SampleState>(`read-sample-state/${sampleId}`)
      setState(s)
      setError(null)
      try {
        setLifecycle(await api.post<SampleLifecycle>('read-sample-lifecycle', { sampleId }))
      } catch {
        setLifecycle(null)
      }
      if (s.activeJourneyId) {
        try {
          setPlan(await api.post<JourneyPlan>('read-journey-plan', { journeyId: s.activeJourneyId }))
        } catch {
          setPlan(null)
        }
      } else setPlan(null)
    } catch (err) {
      setError(describeError(err))
    }
  }, [sampleId])

  useEffect(() => {
    void load()
  }, [load, tick])

  const markers = useMemo<MapMarker[]>(() => {
    if (!state) return []
    const m: MapMarker[] = [{ id: 'origin', coordinate: state.origin, label: 'Sample origin', kind: 'origin' }]
    if (state.latestLocation) {
      m.push({ id: 'sample', coordinate: state.latestLocation, label: `Sample last seen ${fmtTime(state.locationRecordedAt)}`, kind: 'sample', stale: state.locationStale })
    }
    return m
  }, [state])

  const routePath = useMemo<Coordinate[]>(() => {
    if (!state) return []
    const pts: Coordinate[] = [state.origin]
    for (const stop of plan?.orderedStops ?? []) {
      const c = stop.coordinate ?? catalogue.locations.find((l) => l.locationId === stop.locationId)?.coordinate
      if (c) pts.push(c)
    }
    return pts
  }, [state, plan, catalogue.locations])

  if (error) return <Alert kind="error">{error}</Alert>
  if (!state) return <p role="status">Loading sample…</p>

  const status = lifecycle?.status ?? state.state.status
  const isException = status === 'exception' || !!lifecycle?.exception
  const completedStops = plan?.orderedStops.filter((s) => s.completedAt).length ?? 0
  const totalStops = plan?.orderedStops.length ?? 0
  const timeline = lifecycle?.timeline?.length ? lifecycle.timeline : state.timeline

  return (
    <div className="page">
      <h1>
        Sample {sampleId.slice(0, 8)} <StatusBadge status={status} />
      </h1>
      {isException && (
        <Alert kind="error">
          <strong>Exception flagged:</strong> {String(lifecycle?.exception?.reason ?? lifecycle?.exception?.code ?? 'This sample requires attention.')}
        </Alert>
      )}
      {status === 'expired' && <Alert kind="error">This sample expired: no valid route could meet its delivery deadline.</Alert>}
      <div className="two-col">
        <Panel title="Current state">
          <KeyValue
            items={[
              ['Status', <StatusBadge status={status} />],
              ['Serviceability', <StatusBadge status={state.serviceability} />],
              ['Sample type', typeName(state.sampleTypeId)],
              ['Origin', `${humanize(state.originType)} · ${fmtCoord(state.origin)}`],
              ['Requested at', fmtTime(state.requestedAt)],
              ['Delivery deadline', fmtTime(state.deliveryDeadline)],
              ['Container', state.containerType],
              ['Temperature range', `${state.temperatureMinC} °C to ${state.temperatureMaxC} °C`],
              ['Target laboratory', locName(state.targetLaboratoryId)],
              ['Current custodian', lifecycle?.currentHolderId ? (lifecycle.currentHolderId === user?.userId ? 'You' : `Worker ${lifecycle.currentHolderId.slice(0, 8)}`) : 'No custodian yet (not sealed)'],
              ['Sealed', lifecycle ? (lifecycle.sealed ? 'Yes' : 'No') : '—'],
              ['Current / last known location', state.latestLocation ? fmtCoord(state.latestLocation) : 'Not yet reported'],
              ['Last update', fmtTime(state.locationRecordedAt)],
              ['Location freshness', <StaleBadge stale={state.locationStale} recordedAt={state.locationRecordedAt} />],
              ['Route progress', totalStops ? `${completedStops} of ${totalStops} stops completed` : 'No active route'],
              ...(state.activeJourneyId ? ([['Journey', <Link to={`/journeys/${state.activeJourneyId}`}>{state.activeJourneyId.slice(0, 8)}</Link>]] as [string, React.ReactNode][]) : []),
            ]}
          />
          {lifecycle?.pendingHandoff && (
            <p>
              <Badge tone="warn">Handoff pending</Badge> sender confirmed: {lifecycle.pendingHandoff.senderConfirmed ? 'yes' : 'no'}, receiver confirmed:{' '}
              {lifecycle.pendingHandoff.receiverConfirmed ? 'yes' : 'no'}
            </p>
          )}
        </Panel>
        <Panel title="Route">
          <LiveMap locations={catalogue.locations} markers={markers} routePath={routePath} height={360} focus={state.latestLocation ?? state.origin} />
          {plan && (
            <ol className="stops">
              {plan.orderedStops.map((s) => (
                <li key={s.stopId}>
                  <Badge tone={s.completedAt ? 'ok' : 'muted'}>{humanize(s.stopType)}</Badge> {locName(s.locationId)} · ETA {fmtTime(s.estimatedAt)}
                  {s.completedAt && <span className="muted"> · done {fmtTime(s.completedAt)}</span>}
                </li>
              ))}
            </ol>
          )}
        </Panel>
      </div>
      <Panel title="Status history">
        <Timeline entries={timeline} />
      </Panel>
    </div>
  )
}
