{"command": "create", "path": "/workspace/frontend/src/components/RequestForm.tsx", "file_text": "import { useState, type FormEvent } from 'react'
import { Link } from 'react-router-dom'
import { api, describeError, newIdempotencyKey } from '../lib/api'
import { useLocationName, useSession } from '../lib/session'
import type { Coordinate } from '../lib/types'
import { fmtTime, fromLocalInput, humanize, toLocalInput } from '../lib/format'
import { Alert, Field, KeyValue } from './ui'

interface ServiceabilityResult {
  serviceable: boolean
  reason: string
  targetLaboratoryId?: string
  estimatedArrivalAt?: string
  serviceabilityVersion: number
}

interface CreateResult {
  requestId: string
  sampleId: string
  serviceability: string
  serviceabilityReason?: string
  journeyId?: string
  targetLaboratoryId?: string
  activeAssignmentIds: string[]
}

interface Props {
  mode: 'request' | 'presealed'
}

export default function RequestForm({ mode }: Props) {
  const { catalogue } = useSession()
  const locName = useLocationName()
  const presealed = mode === 'presealed'
  const [originType, setOriginType] = useState<'home' | 'clinic' | 'node'>(presealed ? 'node' : 'home')
  const [originNodeId, setOriginNodeId] = useState('')
  const [lat, setLat] = useState('12.9716')
  const [lng, setLng] = useState('77.5946')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [requestedAt] = useState(() => toLocalInput(new Date()))
  const [earliest, setEarliest] = useState(() => toLocalInput(new Date(Date.now() + 30 * 60000)))
  const [latest, setLatest] = useState(() => toLocalInput(new Date(Date.now() + 3 * 3600000)))
  const [deadline, setDeadline] = useState(() => toLocalInput(new Date(Date.now() + 8 * 3600000)))
  const [containerType, setContainerType] = useState('')
  const [tMin, setTMin] = useState('')
  const [tMax, setTMax] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [check, setCheck] = useState<ServiceabilityResult | null>(null)
  const [created, setCreated] = useState<CreateResult | null>(null)
  const [busy, setBusy] = useState(false)

  const selectedType = catalogue.sampleTypes.find((t) => t.sampleTypeId === sampleTypeId)
  const applyTypeDefaults = (id: string) => {
    setSampleTypeId(id)
    const t = catalogue.sampleTypes.find((x) => x.sampleTypeId === id)
    if (t) {
      setContainerType(t.containerType)
      setTMin(String(t.temperatureMinC))
      setTMax(String(t.temperatureMaxC))
    }
  }

  const origin = (): Coordinate => {
    if (originType === 'node' && originNodeId) {
      const n = catalogue.locations.find((l) => l.locationId === originNodeId)
      if (n) return n.coordinate
    }
    return { latitude: Number(lat), longitude: Number(lng) }
  }

  const basePayload = () => {
    const p: Record<string, unknown> = {
      origin: origin(),
      originType,
      sampleTypeId,
      requestedAt: fromLocalInput(requestedAt),
      deliveryDeadline: fromLocalInput(deadline),
      earliestCollectionAt: fromLocalInput(earliest),
      latestCollectionAt: fromLocalInput(latest),
    }
    if (originType === 'node' && originNodeId) p.originNodeId = originNodeId
    return p
  }

  const validate = (): string | null => {
    if (!sampleTypeId) return 'Choose a sample type.'
    if (originType === 'node' && !originNodeId) return 'Choose the network node the sample starts from.'
    if (!deadline) return 'Delivery deadline is required.'
    if (earliest && latest && new Date(earliest) > new Date(latest)) return 'Earliest collection time must be before latest collection time.'
    if (latest && new Date(latest) > new Date(deadline)) return 'Latest collection time must be before the delivery deadline.'
    if (new Date(deadline) <= new Date()) return 'Delivery deadline must be in the future.'
    return null
  }

  const doCheck = async () => {
    setError(null)
    setCreated(null)
    const v = validate()
    if (v) {
      setError(v)
      return
    }
    setBusy(true)
    try {
      setCheck(await api.post<ServiceabilityResult>('check-serviceability', basePayload()))
    } catch (err) {
      setCheck(null)
      setError(describeError(err))
    } finally {
      setBusy(false)
    }
  }

  const submit = async (e: FormEvent) => {
    e.preventDefault()
    setError(null)
    const v = validate()
    if (v) {
      setError(v)
      return
    }
    if (!containerType) {
      setError('Container type is required.')
      return
    }
    if (Number(tMin) > Number(tMax)) {
      setError('Minimum temperature must not exceed maximum temperature.')
      return
    }
    setBusy(true)
    try {
      const res = await api.post<CreateResult>(presealed ? 'ingest-presealed-sample' : 'create-collection-request', {
        ...basePayload(),
        containerType,
        temperatureMinC: Number(tMin),
        temperatureMaxC: Number(tMax),
        idempotencyKey: newIdempotencyKey(),
      })
      setCreated(res)
      setCheck(null)
    } catch (err) {
      setError(describeError(err))
    } finally {
      setBusy(false)
    }
  }

  if (created) {
    return (
      <div className="card">
        <Alert kind={created.serviceability === 'serviceable' ? 'success' : 'info'}>
          {presealed ? 'Pre-sealed sample registered.' : 'Collection request created.'} Serviceability: {humanize(created.serviceability)}
          {created.serviceabilityReason && created.serviceabilityReason !== 'serviceable' ? ` (${humanize(created.serviceabilityReason)})` : ''}
        </Alert>
        <KeyValue
          items={[
            ['Request', created.requestId],
            ['Sample', <Link to={`/samples/${created.sampleId}`}>{created.sampleId}</Link>],
            ['Journey', created.journeyId ? <Link to={`/journeys/${created.journeyId}`}>{created.journeyId}</Link> : '—'],
            ['Target laboratory', locName(created.targetLaboratoryId)],
            ['Assignments created', String(created.activeAssignmentIds.length)],
          ]}
        />
        <button type="button" className="btn btn-secondary" onClick={() => setCreated(null)}>
          Create another
        </button>
      </div>
    )
  }

  const nodes = catalogue.locations.filter((l) => l.active)
  return (
    <form className="card form" onSubmit={submit} aria-label={presealed ? 'Register pre-sealed sample' : 'Collection request'}>
      {error && <Alert kind="error">{error}</Alert>}
      <div className="row">
        <Field label="Origin type">
          <select value={originType} onChange={(e) => setOriginType(e.target.value as 'home' | 'clinic' | 'node')}>
            {!presealed && <option value="home">Patient home</option>}
            <option value="clinic">Clinic</option>
            <option value="node">Network node</option>
          </select>
        </Field>
        {originType === 'node' ? (
          <Field label="Origin node">
            <select value={originNodeId} onChange={(e) => setOriginNodeId(e.target.value)} required>
              <option value="">Select a node…</option>
              {nodes.map((n) => (
                <option key={n.locationId} value={n.locationId}>
                  {n.name}
                </option>
              ))}
            </select>
          </Field>
        ) : (
          <>
            <Field label="Latitude">
              <input type="number" step="any" value={lat} onChange={(e) => setLat(e.target.value)} required />
            </Field>
            <Field label="Longitude">
              <input type="number" step="any" value={lng} onChange={(e) => setLng(e.target.value)} required />
            </Field>
          </>
        )}
      </div>
      <Field label="Sample type">
        <select value={sampleTypeId} onChange={(e) => applyTypeDefaults(e.target.value)} required>
          <option value="">Select a sample type…</option>
          {catalogue.sampleTypes.map((t) => (
            <option key={t.sampleTypeId} value={t.sampleTypeId}>
              {t.name}
            </option>
          ))}
        </select>
      </Field>
      {selectedType && (
        <p className="muted">
          {selectedType.name}: container {selectedType.containerType}, {selectedType.temperatureMinC}–{selectedType.temperatureMaxC} °C
          {selectedType.requiresCooledRoute ? ', cooled route required' : ''}
          {!selectedType.batchingAllowed ? ', no batching (time-critical)' : ''}
          {selectedType.qualifiedCollectorRequired ? `, qualified collector (${selectedType.requiredQualification})` : ''}
        </p>
      )}
      <div className="row">
        <Field label="Earliest collection">
          <input type="datetime-local" value={earliest} onChange={(e) => setEarliest(e.target.value)} />
        </Field>
        <Field label="Latest collection">
          <input type="datetime-local" value={latest} onChange={(e) => setLatest(e.target.value)} />
        </Field>
        <Field label="Delivery deadline">
          <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} required />
        </Field>
      </div>
      <div className="row">
        <Field label="Container type">
          <input value={containerType} onChange={(e) => setContainerType(e.target.value)} />
        </Field>
        <Field label="Min temperature (°C)">
          <input type="number" step="0.1" value={tMin} onChange={(e) => setTMin(e.target.value)} />
        </Field>
        <Field label="Max temperature (°C)">
          <input type="number" step="0.1" value={tMax} onChange={(e) => setTMax(e.target.value)} />
        </Field>
      </div>
      {check && (
        <div role="status" className={`alert ${check.serviceable ? 'alert-success' : 'alert-info'}`} aria-label="Serviceability result">
          <strong>{check.serviceable ? 'Serviceable' : 'Not serviceable'}</strong> — {humanize(check.reason)}
          {check.targetLaboratoryId && <> · laboratory {locName(check.targetLaboratoryId)}</>}
          {check.estimatedArrivalAt && <> · estimated arrival {fmtTime(check.estimatedArrivalAt)}</>}
          <span className="muted"> · serviceability version {check.serviceabilityVersion}. This was a dry run; nothing was created.</span>
        </div>
      )}
      <div className="actions">
        <button type="button" className="btn btn-secondary" disabled={busy} onClick={doCheck}>
          Check serviceability
        </button>
        <button type="submit" className="btn" disabled={busy}>
          {presealed ? 'Register pre-sealed sample' : 'Create request'}
        </button>
      </div>
    </form>
  )
}
