                <th>Sample</th>
                <th>Status</th>
                <th>Current holder</th>
                <th>Deadline</th>
                <th>Last location</th>
                <th>Freshness</th>
                <th>Journey</th>
              </tr>
            </thead>
            <tbody>
              {ops.samples.map((s) => (
                <tr key={s.sampleId}>
                  <td>
                    <Link to={`/samples/${s.sampleId}`}>{s.sampleId.slice(0, 8)}</Link>
                  </td>
                  <td>
                    <StatusBadge status={s.status} />
                  </td>
                  <td>{s.currentHolderId ? workerName(ops, s.currentHolderId) : '—'}</td>
                  <td>{fmtTime(s.deliveryDeadline)}</td>
                  <td>{fmtCoord(s.latestLocation)}</td>
                  <td>
                    <StaleBadge stale={s.locationStale} recordedAt={s.locationRecordedAt} />
