                  <td>{w.fullName ?? w.workerId.slice(0, 8)}</td>
                  <td>{w.roles?.map(humanize).join(', ')}</td>
                  <td>
                    <Badge tone={w.available ? 'ok' : 'warn'}>{humanize(w.status)}</Badge>
