import { Link, useNavigate, useParams } from 'react-router-dom'
import { api, describeError, newIdempotencyKey } from '../lib/api'
import { useLocationName, useSession } from '../lib/session'
import type { JourneyPlan } from '../lib/types'
import { fmtTime, humanize } from '../lib/format'
import { Alert, Badge, Field, KeyValue, Panel, StatusBadge } from '../components/ui'

const CHANGE_TYPES = ['add_stop', 'remove_stop', 'reorder_stops', 'replace_worker', 'reassign_worker', 'merge_samples', 'split_samples', 'split_batch', 'cancel_work', 'reroute', 'replace_route']

export default function JourneyPage() {
