    [query, entityId, action, role, order],
  )

  useEffect(() => {
    void search(0)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const submit = (e: FormEvent) => {
    e.preventDefault()
    void search(0)
  }

  return (
    <div className="page">
      <h1>Audit history</h1>
      <Panel title="Search">
        <form className="form" onSubmit={submit} aria-label="Audit search">
