                <option value="newest_first">Newest first</option>
                <option value="oldest_first">Oldest first</option>
              </select>
            </Field>
          </div>
          <button type="submit" className="btn">
            Search
          </button>
        </form>
      </Panel>
      {error && <Alert kind="error">{error}</Alert>}
      {result && (
        <Panel
          title={`Results (${result.total})`}
          actions={
            <div className="actions">
              <button type="button" className="btn btn-small" disabled={offset === 0} onClick={() => search(Math.max(0, offset - limit))}>
                Previous
              </button>
              <button type="button" className="btn btn-small" disabled={!result.hasMore} onClick={() => search(result.nextOffset ?? offset + limit)}>
                Next
              </button>
            </div>
          }
        >
          {result.entries.length === 0 ? (
            <p className="muted">No audit records match.</p>
          ) : (
            <table className="table audit">
