                  <th>Action</th>
                  <th>User</th>
                  <th>Role</th>
                  <th>Entity</th>
                  <th>Outcome</th>
                  <th>Changes</th>
                </tr>
              </thead>
              <tbody>
                {result.entries.map((e) => (
                  <tr key={e.auditId}>
                    <td>{fmtTime(e.occurredAt)}</td>
                    <td>{humanize(e.action)}</td>
                    <td>{e.actorId ? e.actorId.slice(0, 8) : 'anonymous'}</td>
                    <td>{humanize(e.role)}</td>
                    <td>
