import { api, describeError } from '../lib/api'
import { useSession } from '../lib/session'
import { humanize } from '../lib/format'
import { Alert, Field, KeyValue, Panel } from '../components/ui'

export default function CapacityPage() {
  const { catalogue, assignedLocationId, user } = useSession()
  const location = catalogue.locations.find((l) => l.locationId === assignedLocationId)
  const [regular, setRegular] = useState('')
  const [cooled, setCooled] = useState('')
  const [notice, setNotice] = useState<{ kind: 'error' | 'success'; text: string } | null>(null)

  useEffect(() => {
    if (location?.capacity) {
      setRegular(String(location.capacity.capacityUnits))
      setCooled(String(location.capacity.cooledCapacityUnits))
    }
  }, [location?.capacity?.capacityUnits, location?.capacity?.cooledCapacityUnits])

  const submit = async (e: FormEvent) => {
    e.preventDefault()
    if (!location) return
    setNotice(null)
    try {
      await api.post('configure-capacity', { resourceId: location.locationId, capacityUnits: Number(regular), cooledCapacityUnits: Number(cooled) })
      setNotice({ kind: 'success', text: 'Capacity updated.' })
    } catch (err) {
      setNotice({ kind: 'error', text: describeError(err) })
    }
  }

  const kind = user?.activeRole === 'laboratory_team' ? 'laboratory' : 'node'
  if (!assignedLocationId) {
    return (
      <div className="page">
        <h1>Capacity</h1>
        <Alert kind="info">You are not assigned to a {kind}. Ask an administrator to assign you to one.</Alert>
      </div>
    )
  }
  if (!location) return <p role="status">Loading your {kind}…</p>
  const cap = location.capacity

  return (
    <div className="page">
      <h1>Capacity at {location.name}</h1>
      <div className="two-col">
        <Panel title={`Your ${kind}`}>
          <KeyValue
            items={[
              ['Name', location.name],
              ['Functions', Object.entries(location.functions).filter(([, v]) => v).map(([k]) => humanize(k)).join(', ')],
              ['Active', location.active ? 'yes' : 'no'],
              ['Handling time', `${location.handlingMinutes} min`],
              ['Regular capacity', cap ? `${cap.capacityUnits} configured · ${cap.reservedUnits} reserved · ${cap.availableUnits} available` : '—'],
              ['Cooled capacity', cap ? `${cap.cooledCapacityUnits} configured · ${cap.cooledReservedUnits} reserved · ${cap.cooledAvailableUnits} available` : '—'],
            ]}
          />
        </Panel>
        <Panel title="Configure capacity">
          {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
          <form className="form" onSubmit={submit} aria-label="Configure capacity">
            <Field label="Regular capacity units">
              <input type="number" min={0} value={regular} onChange={(e) => setRegular(e.target.value)} required />
            </Field>
            <Field label="Cooled capacity units">
              <input type="number" min={0} value={cooled} onChange={(e) => setCooled(e.target.value)} required />
            </Field>
            <button type="submit" className="btn">
              Save capacity
            </button>
          </form>
        </Panel>
      </div>
    </div>
  )
}
