    </div>
  )
}

function useRunner(): [Notice, (label: string, fn: () => Promise<unknown>) => Promise<boolean>] {
  const [notice, setNotice] = useState<Notice>(null)
  const run = async (label: string, fn: () => Promise<unknown>) => {
    setNotice(null)
    try {
      await fn()
      setNotice({ kind: 'success', text: `${label} saved.` })
      return true
    } catch (err) {
      setNotice({ kind: 'error', text: describeError(err) })
      return false
    }
  }
  return [notice, run]
}

